import React from 'react'
import { useNavigate } from 'react-router-dom';
import { UserRound, LayoutDashboard, Bot, BarChart3, ClipboardCheck, Settings, LifeBuoy, LogOut } from "lucide-react";
function Sidebar({collasped, mobileMenuOpen, onToggle, activeTab, onPageChange}) {
    const navigate = useNavigate();
    const menuItems =[
        {
        id: "dashboard",
        title: "Dashboard",
        icon: LayoutDashboard,
    },
    {
        id: "health-assistant",
        title: "Health Assistant",
        icon: Bot,
    },
    {
        id: "reports",
        title: "Reports",
        icon: ClipboardCheck,
    },
    {
        id: "settings",
        title: "Settings",
        icon: Settings,
    },
    {
        id: "help",
        title: "Help",
        icon: LifeBuoy,
    },
    ]
  return (
    <div className={`
      ${mobileMenuOpen ? 'flex translate-x-0' : 'hidden md:flex'} 
      fixed md:relative z-50 h-full w-64
      ${collasped ? 'md:w-20' : 'md:w-64'} 
      transition-all duration-300 ease-in-out bg-white/95 dark:bg-slate-900/95 backdrop-blur-xl border-r border-gray-200/50 dark:border-slate-700/50 flex-col
    `}>
        {/* Logo */}
    <div className={`border-b border-gray-200/50 dark:border-slate-700/50 flex items-center ${collasped ? 'md:p-4 md:justify-center p-6 justify-between' : 'p-6 justify-between'}`}>
        <div className='flex items-center gap-3'>
            <img src="/favicon.ico" alt="logo" className='w-10 h-10 flex-shrink-0' />
            {(!collasped || mobileMenuOpen) && (
                <div className='flex flex-col'>
                    <h1 className={`${collasped && !mobileMenuOpen ? 'md:hidden' : ''} text-xl font-black dark:text-white whitespace-nowrap`}>Digital Health Twin</h1>
                    <p className={`${collasped && !mobileMenuOpen ? 'md:hidden' : ''} text-sm text-gray-500 dark:text-gray-400 whitespace-nowrap`}>User Profile</p>
                </div>
            )}
        </div>
    </div>

    {/* Navigation */}
    <nav className='flex-1 overflow-y-auto p-4 space-y-2'> 
        {menuItems.map((item) => (
            <button
            key={item.id}
            onClick={() => onPageChange && onPageChange(item.id)}
            className={`w-full flex items-center ${collasped && !mobileMenuOpen ? 'md:justify-center md:px-0 px-4 gap-3' : 'gap-3 px-4'} py-3 rounded-xl transition-colors duration-200 ${activeTab === item.id || item.active ? 'bg-gradient-to-r from-teal-300/10 to-teal-500/30 text-teal-500 dark:bg-gradient-to-r from-slate-800/50 to-primary/50 shadow-lg' : 'text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800'}`}
            >
                <item.icon className='w-5 h-5 flex-shrink-0'/>
                {(!collasped || mobileMenuOpen) && <span className={`${collasped && !mobileMenuOpen ? 'md:hidden' : ''} font-medium whitespace-nowrap`}>{item.title}</span>}
            </button>
        ))}
    </nav>
    
    {/* Logout Option */}
    <div className="px-4 pb-4">
        <button
            onClick={() => navigate('/')}
            className={`w-full flex items-center ${collasped && !mobileMenuOpen ? 'md:justify-center md:px-0 px-4 gap-3' : 'gap-3 px-4'} py-3 rounded-xl transition-colors duration-200 text-red-500 hover:bg-red-50 dark:text-red-400 dark:hover:bg-red-500/10`}
        >
            <LogOut className='w-5 h-5 flex-shrink-0'/>
            {(!collasped || mobileMenuOpen) && <span className={`${collasped && !mobileMenuOpen ? 'md:hidden' : ''} font-medium whitespace-nowrap`}>Logout</span>}
        </button>
    </div>

    {/* User Profile */}
    <div className={`border-t border-gray-200/50 dark:border-slate-700/50 ${collasped && !mobileMenuOpen ? 'md:p-4 md:flex md:justify-center p-6' : 'p-6'}`}>
        <div className='flex items-center gap-3'>
           <div className='rounded-full bg-primary flex-shrink-0 w-10 h-10 flex items-center justify-center text-white font-bold'>
            <UserRound size={20} />
           </div>
           {(!collasped || mobileMenuOpen) && (
            <div className={`flex flex-col ${collasped && !mobileMenuOpen ? 'md:hidden' : ''}`}>
                <h1 className='text-lg font-black dark:text-white mt-2 whitespace-nowrap'>User Name</h1>
                <p className='text-sm text-gray-500 dark:text-gray-400 -mt-2 whitespace-nowrap'>user@email.com</p>
            </div>
           )}
        </div>
    </div>

      
    </div>
  )
}

export default Sidebar

import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { motion } from "framer-motion";
import assets from "../assets/assets";
import { authService } from "../api/authService";
import { useAuth } from "../contexts/AuthContext";

export default function Login() {
  const navigate = useNavigate();
  const { loginContext, user } = useAuth();

  useEffect(() => {
    if (user) {
      navigate('/dashboard');
    }
  }, [user, navigate]);

  const [form, setForm] = useState({
    email: "",
    password: "",
  });

  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setForm({
      ...form,
      [e.target.name]: e.target.value,
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!form.email || !form.password) {
      return setError("Please fill all fields");
    }

    if (form.password.length < 6) {
      return setError("Password must be at least 6 characters");
    }

    setError("");
    setLoading(true);

    try {
      const response = await authService.login({
        email: form.email,
        password: form.password,
      });

      // Assuming response contains { user, token or access_token }
      const token = response.token || response.access_token;
      
      loginContext(response.user, token);      
      navigate("/dashboard");
    } catch (err) {
      // Show backend error if available, else generic
      const errorMessage = err.response?.data?.message || err.response?.data?.detail || "Invalid credentials.";
      setError(errorMessage);
    } finally {
      setLoading(false);
    }
  };

  return (
      <div className="min-h-screen flex items-center justify-center bg-linear-to-br from-gray-100 from-20% via-teal-300 via-50% to-white to-90% dark:bg-linear-to-br dark:from-black dark:from-20% dark:via-teal-300 dark:via-50% dark:to-black dark:to-90% px-4 ">
      <div className="w-full max-w-5xl md:max-h-160 grid md:grid-cols-2 -ml-10 -mr-10 bg-blur-2xl bg-white/40 dark:bg-zinc-900 shadow-lg overflow-hidden border-t-2 border-primary rounded-3xl">

        {/* RIGHT FORM */}
        <motion.div 
        animate={{ x: 0, opacity: 1 }}
        exit={{ x: "100%", opacity: 0.3 }}
        transition={{ duration: 0.5, ease: "easeInOut" }}
      >
        <div className="p-8 justify-center py-15 mt-22">
          <div className="flex justify-center w-full h-fit">
            <h2 className="text-4xl font-black text-teal-800 dark:text-white mb-10">
              Welcome Back
            </h2>
          </div>

          {error && (
            <div className="bg-red-100 dark:bg-red-900/30 text-red-600 dark:text-red-400 p-3 rounded mb-4 text-sm">
              {error}
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-4">

            <input
              type="email"
              name="email"
              placeholder="Email"
              value={form.email}
              onChange={handleChange}
              className="w-full p-3 border rounded-lg mb-8 focus:ring-2 focus:ring-teal-400 outline-none bg-white dark:bg-zinc-800 border-gray-300 dark:border-zinc-700 text-gray-900 dark:text-white placeholder-gray-400 dark:placeholder-gray-500"
            />

            <input
              type="password"
              name="password"
              placeholder="Password"
              value={form.password}
              onChange={handleChange}
              className="w-full p-3 border rounded-lg mb-8 focus:ring-2 focus:ring-teal-400 outline-none bg-white dark:bg-zinc-800 border-gray-300 dark:border-zinc-700 text-gray-900 dark:text-white placeholder-gray-400 dark:placeholder-gray-500"
            />

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-teal-500 text-white py-3 rounded-lg font-semibold hover:bg-teal-600 transition"
            >
              {loading ? "Signing In..." : "Sign In"}
            </button>

          </form>

          <p className="text-sm text-gray-500 dark:text-gray-400 mt-6 text-center">
            DonΓÇÖt have an account?{" "}
            <span
              onClick={() => navigate("/signup")}
              className="text-teal-500 cursor-pointer"
            >
              Sign Up
            </span>
          </p>

        </div>
        </motion.div>
        <motion.div 
        animate={{ x: 0, opacity: 1 }}
        exit={{ x: "-100%", opacity: 0.3 }}
        transition={{ duration: 0.5, ease: "easeInOut" }}
      >
        <div className="hidden md:block">
          <img
            src={assets.signin}
            className="w-full h-full object-cover min-h-50 -translate-y-18 dark:hidden block"
          />
          <img
            src={assets.signin_dark}
            className="w-full h-full object-cover min-h-50 -translate-y-18 hidden dark:block"
          />
        </div>
        </motion.div>
    </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { motion } from "framer-motion";
import assets from "../assets/assets";
import { authService } from "../api/authService";
import { useAuth } from "../contexts/AuthContext";

export default function Signup() {
  const navigate = useNavigate();
  const { loginContext, user } = useAuth();

  useEffect(() => {
    if (user) {
      navigate('/dashboard');
    }
  }, [user, navigate]);

  const [form, setForm] = useState({
    name: "",
    surname: "",
    email: "",
    password: "",
    confirmPassword: "",
  });

  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setForm({
      ...form,
      [e.target.name]: e.target.value,
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!form.name || !form.surname || !form.email || !form.password) {
      return setError("Please fill all fields");
    }

    if (form.password.length < 6) {
      return setError("Password must be at least 6 characters");
    }

    if (form.password !== form.confirmPassword) {
      return setError("Passwords do not match");
    }

    setError("");
    setLoading(true);

    try {
      const response = await authService.register({
        name: `${form.name} ${form.surname}`.trim(),
        email: form.email,
        password: form.password,
      });

      // Based on API spec, it usually returns { user, token or access_token } if it Auto-logs in
      // If it doesn't return a token, we might need to call login immediately after. Let's assume it logs them in and returns a token. 
      // If the backend doesn't auto-login, we'd navigate to login instead:
      if (response.token || response.access_token) {
        const token = response.token || response.access_token;
        loginContext(response.user, token);
        navigate("/dashboard");
      } else {
         // Fallback if the backend requires a manual login step
         navigate("/login");
      }
    } catch (err) {
      const errorMessage = err.response?.data?.message || err.response?.data?.detail || "Something went wrong.";
      setError(errorMessage);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-linear-to-br from-gray-100 from-20% via-teal-300 via-50% to-white to-90% dark:bg-linear-to-br dark:from-black dark:from-20% dark:via-teal-300 dark:via-50% dark:to-black dark:to-90% px-4 ">

    <div className="w-full max-w-5xl md:max-h-160 grid md:grid-cols-2 -ml-10 -mr-10 bg-blur-2xl bg-white/40 dark:bg-zinc-900 shadow-lg overflow-hidden border-t-2 border-primary rounded-3xl">

      {/* LEFT IMAGE */}
      <motion.div 
        animate={{ x: 0, opacity: 1 }}
        exit={{ x: "100%", opacity: 0.3 }}
        transition={{ duration: 0.5, ease: "easeInOut" }}
      >
      <div className="hidden md:block">
        <img
          src={assets.signin}
          className="w-full h-full object-cover min-h-50 -translate-y-18 dark:hidden block"
        />
        <img
          src={assets.signin_dark}
          className="w-full h-full object-cover min-h-50 -translate-y-18 hidden dark:block"
        />
      </div>
      </motion.div>

      {/* RIGHT FORM */}
      <motion.div 
        animate={{ x: 0, opacity: 1 }}
        exit={{ x: "-100%", opacity: 0.3 }}
        transition={{ duration: 0.5, ease: "easeInOut" }}
      >
      <div className="p-8 justify-center py-15">
        <div className="flex justify-center w-full h-fit">
        <h2 className="text-4xl font-black text-teal-800 dark:text-white mb-6">
          Create Account
        </h2>

        </div>
        

        {error && (
          <div className="bg-red-100 dark:bg-red-900/30 text-red-600 dark:text-red-400 p-3 rounded mb-4 text-sm">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-4">

          <input
            type="text"
            name="name"
            placeholder="First Name"
            value={form.name}
            onChange={handleChange}
            className="w-full p-3 border rounded-lg focus:ring-2 focus:ring-teal-400 outline-none bg-white dark:bg-zinc-800 border-gray-300 dark:border-zinc-700 text-gray-900 dark:text-white placeholder-gray-400 dark:placeholder-gray-500"
          />

          <input
            type="text"
            name="surname"
            placeholder="Surname"
            value={form.surname}
            onChange={handleChange}
            className="w-full p-3 border rounded-lg focus:ring-2 focus:ring-teal-400 outline-none bg-white dark:bg-zinc-800 border-gray-300 dark:border-zinc-700 text-gray-900 dark:text-white placeholder-gray-400 dark:placeholder-gray-500"
          />

          <input
            type="email"
            name="email"
            placeholder="Email"
            value={form.email}
            onChange={handleChange}
            className="w-full p-3 border rounded-lg focus:ring-2 focus:ring-teal-400 outline-none bg-white dark:bg-zinc-800 border-gray-300 dark:border-zinc-700 text-gray-900 dark:text-white placeholder-gray-400 dark:placeholder-gray-500"
          />

          <input
            type="password"
            name="password"
            placeholder="Password"
            value={form.password}
            onChange={handleChange}
            className="w-full p-3 border rounded-lg focus:ring-2 focus:ring-teal-400 outline-none bg-white dark:bg-zinc-800 border-gray-300 dark:border-zinc-700 text-gray-900 dark:text-white placeholder-gray-400 dark:placeholder-gray-500"
          />

          <input
            type="password"
            name="confirmPassword"
            placeholder="Confirm Password"
            value={form.confirmPassword}
            onChange={handleChange}
            className="w-full p-3 border rounded-lg focus:ring-2 focus:ring-teal-400 outline-none bg-white dark:bg-zinc-800 border-gray-300 dark:border-zinc-700 text-gray-900 dark:text-white placeholder-gray-400 dark:placeholder-gray-500"
          />

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-teal-500 text-white py-3 rounded-lg font-semibold hover:bg-teal-600 transition"
          >
            {loading ? "Creating Account..." : "Sign Up"}
          </button>

        </form>

        <p className="text-sm text-gray-500 dark:text-gray-400 mt-6 text-center">
          Already have an account?{" "}
          <span
            onClick={() => navigate("/login")}
            className="text-teal-500 cursor-pointer"
          >
            Sign In
          </span>
        </p>

      </div>
      </motion.div>

    </div>
    </div>
);
}

import React, { createContext, useContext, useState, useEffect } from 'react';
import { authService } from '../api/authService';

const AuthContext = createContext(null);

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(() => {
    const savedUser = localStorage.getItem('user');
    return savedUser ? JSON.parse(savedUser) : null;
  });

  const [token, setToken] = useState(() => localStorage.getItem('token'));

  // We don't inherently need a global loading state for standard login/signup if we handle it in components, 
  // but it's useful if we check auth state on mount.
  const [loading, setLoading] = useState(false);

  // Auto-login or validate token on mount could be done here if there was an endpoint like /auth/me.
  // For now, we rely on local storage presence.

  const loginContext = (userData, userToken) => {
    setUser(userData);
    setToken(userToken);
    localStorage.setItem('user', JSON.stringify(userData));
    localStorage.setItem('token', userToken);
  };

  const logoutContext = () => {
    setUser(null);
    setToken(null);
    localStorage.removeItem('user');
    localStorage.removeItem('token');
  };

  const value = {
    user,
    token,
    loading,
    loginContext,
    logoutContext,
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};
